pub mod caps {
    use crate::json::Writer;

    #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
    pub enum Capability {
        FsRead,
        FsWrite,
        ProcessExec,
        Network,
        Internet,
        Crypto,
        KeyAccess,
        Jni,
        Native,
        TempStorage,
        Cache,
        Device,
        SensitiveOutput,
    }

    impl Capability {
        pub const fn as_str(self) -> &'static str {
            match self {
                Capability::FsRead => "FS_READ",
                Capability::FsWrite => "FS_WRITE",
                Capability::ProcessExec => "PROCESS_EXEC",
                Capability::Network => "NETWORK",
                Capability::Internet => "INTERNET",
                Capability::Crypto => "CRYPTO",
                Capability::KeyAccess => "KEY_ACCESS",
                Capability::Jni => "JNI",
                Capability::Native => "NATIVE",
                Capability::TempStorage => "TEMP_STORAGE",
                Capability::Cache => "CACHE",
                Capability::Device => "DEVICE",
                Capability::SensitiveOutput => "SENSITIVE_OUTPUT",
            }
        }

        pub const ALL: &'static [Capability] = &[
            Capability::FsRead,
            Capability::FsWrite,
            Capability::ProcessExec,
            Capability::Network,
            Capability::Internet,
            Capability::Crypto,
            Capability::KeyAccess,
            Capability::Jni,
            Capability::Native,
            Capability::TempStorage,
            Capability::Cache,
            Capability::Device,
            Capability::SensitiveOutput,
        ];

        pub const fn is_sensitive(self) -> bool {
            matches!(
                self,
                Capability::KeyAccess
                    | Capability::Crypto
                    | Capability::SensitiveOutput
                    | Capability::ProcessExec
                    | Capability::Network
                    | Capability::Internet
            )
        }
    }

    impl core::fmt::Display for Capability {
        fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
            f.write_str(self.as_str())
        }
    }

    #[derive(Clone, Copy, PartialEq, Eq, Debug, Hash)]
    pub enum Decision {
        Grant,
        Deny,
    }

    impl Decision {
        pub const fn as_str(self) -> &'static str {
            match self {
                Decision::Grant => "GRANT",
                Decision::Deny => "DENY",
            }
        }

        pub const fn is_granted(self) -> bool {
            matches!(self, Decision::Grant)
        }
    }

    #[derive(Clone, PartialEq, Eq, Debug)]
    pub struct AuditRecord {
        pub subject: String,
        pub capability: Capability,
        pub decision: Decision,
        pub reason: String,
    }

    #[derive(Clone, Debug)]
    pub struct Policy {
        name: String,
        granted: Vec<Capability>,
        audit: Vec<AuditRecord>,
    }

    impl Policy {
        pub fn new(name: impl Into<String>) -> Self {
            Policy {
                name: name.into(),
                granted: Vec::new(),
                audit: Vec::new(),
            }
        }

        pub fn name(&self) -> &str {
            &self.name
        }

        pub fn grant(&mut self, capability: Capability) -> &mut Self {
            if !self.granted.contains(&capability) {
                self.granted.push(capability);
                self.granted.sort();
            }
            self
        }

        pub fn revoke(&mut self, capability: Capability) -> &mut Self {
            self.granted.retain(|c| *c != capability);
            self
        }

        pub fn granted(&self) -> &[Capability] {
            &self.granted
        }

        pub fn request(&mut self, subject: &str, capability: Capability) -> Decision {
            let decision = if self.granted.contains(&capability) {
                Decision::Grant
            } else {
                Decision::Deny
            };
            let reason = match decision {
                Decision::Grant => format!("granted by policy '{}'", self.name),
                Decision::Deny => format!("not granted by policy '{}' (default deny)", self.name),
            };
            self.audit.push(AuditRecord {
                subject: subject.to_string(),
                capability,
                decision,
                reason,
            });
            decision
        }

        pub fn audit(&self) -> &[AuditRecord] {
            &self.audit
        }

        pub fn absorb(&mut self, records: Vec<AuditRecord>) {
            self.audit.extend(records);
        }

        pub fn write_json(&self, w: &mut Writer, key: &str) {
            w.begin_object(Some(key));
            w.field_str("name", &self.name);
            w.field_str("default", "DENY");
            w.begin_array(Some("granted"));
            for c in &self.granted {
                w.element_str(c.as_str());
            }
            w.end_array();
            w.begin_array(Some("audit"));
            for record in &self.audit {
                w.begin_object(None);
                w.field_str("subject", &record.subject);
                w.field_str("capability", record.capability.as_str());
                w.field_str("decision", record.decision.as_str());
                w.field_str("reason", &record.reason);
                w.field_bool("sensitive", record.capability.is_sensitive());
                w.end_object();
            }
            w.end_array();
            w.end_object();
        }
    }
}

pub mod plugin {
    use crate::caps::{Capability, Decision, Policy};
    use crate::diag::{Diagnostic, Severity};
    use crate::json::Writer;
    use crate::FailureClass;

    #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
    pub struct Version {
        pub major: u16,
        pub minor: u16,
        pub patch: u16,
    }

    impl Version {
        pub const fn new(major: u16, minor: u16, patch: u16) -> Self {
            Version {
                major,
                minor,
                patch,
            }
        }

        pub const fn is_compatible_with(self, required: Version) -> bool {
            self.major == required.major
                && (self.minor > required.minor
                    || (self.minor == required.minor && self.patch >= required.patch))
        }
    }

    impl core::fmt::Display for Version {
        fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
            write!(f, "{}.{}.{}", self.major, self.minor, self.patch)
        }
    }

    #[derive(Clone, Copy, Debug)]
    pub struct Contract {
        pub id: &'static str,
        pub display_name: &'static str,
        pub version: Version,
        pub produces_artifacts: bool,
        pub summary: &'static str,
        pub inputs: &'static [&'static str],
        pub outputs: &'static [&'static str],
        pub required_capabilities: &'static [Capability],
        pub forbidden_capabilities: &'static [Capability],
        pub non_responsibilities: &'static [&'static str],
    }

    impl Contract {
        pub fn write_json(&self, w: &mut Writer) {
            w.begin_object(None);
            w.field_str("id", self.id);
            w.field_str("displayName", self.display_name);
            w.field_str("version", &self.version.to_string());
            w.field_bool("mayProduceArtifacts", self.produces_artifacts);
            w.field_str("summary", self.summary);
            w.begin_array(Some("inputs"));
            for i in self.inputs {
                w.element_str(i);
            }
            w.end_array();
            w.begin_array(Some("outputs"));
            for o in self.outputs {
                w.element_str(o);
            }
            w.end_array();
            w.begin_array(Some("requiredCapabilities"));
            for c in self.required_capabilities {
                w.element_str(c.as_str());
            }
            w.end_array();
            w.begin_array(Some("forbiddenCapabilities"));
            for c in self.forbidden_capabilities {
                w.element_str(c.as_str());
            }
            w.end_array();
            w.begin_array(Some("nonResponsibilities"));
            for n in self.non_responsibilities {
                w.element_str(n);
            }
            w.end_array();
            w.end_object();
        }
    }

    #[derive(Clone, Debug, Default)]
    pub struct Outcome {
        pub artifacts: Vec<String>,
    }

    #[derive(Debug)]
    pub struct Context<'a> {
        pub policy: &'a mut Policy,
        pub diagnostics: &'a mut crate::diag::Sink,
    }

    impl Context<'_> {
        pub fn require(&mut self, subject: &str, capability: Capability) -> Decision {
            self.policy.request(subject, capability)
        }
    }

    #[allow(unreachable_pub)]
    pub trait Plugin: Sync {
        fn contract(&self) -> &'static Contract;

        fn execute(&self, ctx: &mut Context<'_>) -> Result<Outcome, Diagnostic>;
    }

    pub fn unimplemented_diagnostic(contract: &Contract) -> Diagnostic {
        Diagnostic::new(
            "E0001",
            Severity::Error,
            FailureClass::InternalError,
            contract.id,
            format!("{} is not implemented here.", contract.display_name),
        )
        .with_context(format!("Contract version: {}", contract.version))
        .with_context(format!("Declared outputs: {}", contract.outputs.join(", ")))
        .with_suggestion(
            "This subsystem is declared, not built. Nothing was produced and \
             nothing should be expected from it.",
        )
    }

    static BUILTIN: &[&'static dyn Plugin] = &[
        &crate::compilers::kotlin::PLUGIN,
        &crate::compilers::java::PLUGIN,
        &crate::compilers::cpp::PLUGIN,
        &crate::compilers::rust::PLUGIN,
    ];

    #[derive(Clone, Copy)]
    pub struct Registry {
        plugins: &'static [&'static dyn Plugin],
    }

    impl Registry {
        pub fn builtin() -> Self {
            Registry { plugins: BUILTIN }
        }

        pub fn len(&self) -> usize {
            self.plugins.len()
        }

        pub fn is_empty(&self) -> bool {
            self.plugins.is_empty()
        }

        pub fn all(&self) -> &'static [&'static dyn Plugin] {
            self.plugins
        }

        pub fn find(&self, id: &str) -> Option<&'static dyn Plugin> {
            self.plugins.iter().copied().find(|p| p.contract().id == id)
        }

        pub fn write_json(&self, w: &mut Writer, key: &str) {
            w.begin_array(Some(key));
            for p in self.plugins {
                p.contract().write_json(w);
            }
            w.end_array();
        }
    }
}

pub mod compiler {
    use crate::cache;
    use crate::caps::{Capability, Decision, Policy};
    use crate::diag::{Diagnostic, Severity, Sink};
    use crate::hash::{sha256, Digest};
    use crate::json::Writer;
    use crate::plugin::Contract;
    use crate::store::Store;
    use crate::FailureClass;
    use std::sync::atomic::{AtomicBool, Ordering};
    use std::sync::Arc;

    fn fail(origin: &str, code: &str, message: impl Into<String>) -> Diagnostic {
        Diagnostic::new(
            code,
            Severity::Error,
            FailureClass::InternalError,
            origin,
            message,
        )
    }

    #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
    pub enum Abi {
        Arm64V8a,
    }

    impl Abi {
        pub const ALL: &'static [Abi] = &[Abi::Arm64V8a];

        pub const fn as_str(self) -> &'static str {
            match self {
                Abi::Arm64V8a => "arm64-v8a",
            }
        }

        pub fn parse(value: &str) -> Option<Abi> {
            Abi::ALL.iter().copied().find(|abi| abi.as_str() == value)
        }
    }

    pub const OLDEST_API: u32 = 30;
    pub const NEWEST_API: u32 = 37;

    pub const NEWEST_DESCRIBED_API: u32 = 37;

    pub const fn api_is_supported(level: u32) -> bool {
        level >= OLDEST_API && level <= NEWEST_API
    }

    #[derive(Clone, PartialEq, Eq, Debug)]
    pub struct Identity {
        pub language: String,
        pub compiler: String,
        pub version: String,
        pub target: String,

        pub components: Vec<(String, String)>,
    }

    impl Identity {
        pub fn new(
            language: impl Into<String>,
            compiler: impl Into<String>,
            version: impl Into<String>,
            target: impl Into<String>,
        ) -> Identity {
            Identity {
                language: language.into(),
                compiler: compiler.into(),
                version: version.into(),
                target: target.into(),
                components: Vec::new(),
            }
        }

        pub fn with(mut self, name: impl Into<String>, value: impl Into<String>) -> Identity {
            self.components.push((name.into(), value.into()));
            self
        }

        pub fn canonical(&self) -> crate::canonical::Record {
            let components: Vec<(String, Vec<u8>)> = self
                .components
                .iter()
                .map(|(name, value)| (name.clone(), value.as_bytes().to_vec()))
                .collect();
            let mut record = crate::canonical::Record::new();
            record
                .text("language", &self.language)
                .text("compiler", &self.compiler)
                .text("version", &self.version)
                .text("target", &self.target)
                .table("components", &components);
            record
        }

        pub fn digest(&self) -> Digest {
            self.canonical().to_digest()
        }

        pub fn write_json(&self, w: &mut Writer, key: &str) {
            w.begin_object(Some(key));
            w.field_str("language", &self.language);
            w.field_str("compiler", &self.compiler);
            w.field_str("version", &self.version);
            w.field_str("target", &self.target);
            w.begin_array(Some("components"));
            for (name, value) in &self.components {
                w.begin_object(None);
                w.field_str("name", name);
                w.field_str("value", value);
                w.end_object();
            }
            w.end_array();
            w.field_str("digest", &self.digest().to_hex());
            w.end_object();
        }
    }

    #[derive(Clone, PartialEq, Eq, Debug)]
    pub enum Reproducibility {
        Always,

        Given(Vec<String>),

        Unknown,
    }

    impl Reproducibility {
        pub fn as_str(&self) -> &'static str {
            match self {
                Reproducibility::Always => "ALWAYS",
                Reproducibility::Given(_) => "GIVEN",
                Reproducibility::Unknown => "UNKNOWN",
            }
        }
    }

    #[derive(Clone, PartialEq, Eq, Debug)]
    pub struct Source {
        pub path: String,
        pub digest: Digest,
        pub bytes: u64,
    }

    impl Source {
        pub fn of(path: impl Into<String>, content: &[u8]) -> Source {
            Source {
                path: path.into(),
                digest: sha256(content),
                bytes: content.len() as u64,
            }
        }
    }

    #[derive(Clone, PartialEq, Eq, Debug)]
    pub struct Request {
        pub sources: Vec<Source>,

        pub dependencies: Vec<Digest>,
        pub abi: Abi,
        pub api_level: u32,
        pub optimise: bool,
        pub debug_info: bool,
        pub options: Vec<(String, String)>,
    }

    impl Request {
        pub fn new(abi: Abi, api_level: u32) -> Request {
            Request {
                sources: Vec::new(),
                dependencies: Vec::new(),
                abi,
                api_level,
                optimise: true,
                debug_info: false,
                options: Vec::new(),
            }
        }

        pub fn with_source(mut self, source: Source) -> Request {
            self.sources.push(source);
            self
        }

        pub fn ordered_sources(&self) -> Vec<Source> {
            let mut sorted = self.sources.clone();
            sorted.sort_by(|left, right| {
                left.path
                    .cmp(&right.path)
                    .then_with(|| left.digest.cmp(&right.digest))
            });
            sorted
        }

        pub fn canonical(&self) -> crate::canonical::Record {
            let sources: Vec<Vec<u8>> = self
                .ordered_sources()
                .iter()
                .map(|source| {
                    let mut one = crate::canonical::Record::new();
                    one.text("path", &source.path)
                        .digest("digest", source.digest);
                    one.encode()
                })
                .collect();

            let dependencies: Vec<Vec<u8>> = {
                let mut sorted: Vec<Digest> = self.dependencies.clone();
                sorted.sort();
                sorted.dedup();
                sorted
                    .iter()
                    .map(|digest| digest.as_bytes().to_vec())
                    .collect()
            };

            let options: Vec<(String, Vec<u8>)> = self
                .options
                .iter()
                .map(|(name, value)| (name.clone(), value.as_bytes().to_vec()))
                .collect();

            let mut record = crate::canonical::Record::new();
            record
                .sequence("sources", &sources)
                .set("dependencies", &dependencies)
                .text("abi", self.abi.as_str())
                .number("api", u64::from(self.api_level))
                .flag("optimise", self.optimise)
                .flag("debugInfo", self.debug_info)
                .table("options", &options);
            record
        }
    }

    #[derive(Clone, Debug)]
    pub struct Probe {
        pub identity: Option<Identity>,
        pub reproducibility: Reproducibility,

        pub unavailable: Option<Diagnostic>,
    }

    impl Probe {
        pub fn usable(identity: Identity, reproducibility: Reproducibility) -> Probe {
            Probe {
                identity: Some(identity),
                reproducibility,
                unavailable: None,
            }
        }

        pub fn unavailable(why: Diagnostic) -> Probe {
            Probe {
                identity: None,
                reproducibility: Reproducibility::Unknown,
                unavailable: Some(why),
            }
        }

        pub fn is_usable(&self) -> bool {
            self.identity.is_some()
        }

        pub fn write_json(&self, w: &mut Writer, key: &str) {
            w.begin_object(Some(key));
            w.field_bool("usable", self.is_usable());
            w.field_str("reproducibility", self.reproducibility.as_str());
            if let Reproducibility::Given(conditions) = &self.reproducibility {
                w.begin_array(Some("reproducibleGiven"));
                for condition in conditions {
                    w.element_str(condition);
                }
                w.end_array();
            }
            match &self.identity {
                Some(identity) => identity.write_json(w, "identity"),
                None => {
                    if let Some(why) = &self.unavailable {
                        w.field_str("unavailable", &why.message);
                    }
                }
            }
            w.end_object();
        }
    }

    #[derive(Clone, PartialEq, Eq, Debug)]
    pub struct Expected {
        pub name: String,
        pub kind: Kind,
    }

    #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
    pub enum Kind {
        JvmClass,
        Dex,
        Object,
        SharedObject,
        StaticLibrary,
        Resource,
        Metadata,
    }

    impl Kind {
        pub const fn as_str(self) -> &'static str {
            match self {
                Kind::JvmClass => "jvm.class",
                Kind::Dex => "dex",
                Kind::Object => "native.object",
                Kind::SharedObject => "native.shared",
                Kind::StaticLibrary => "native.static",
                Kind::Resource => "resource",
                Kind::Metadata => "metadata",
            }
        }
    }

    #[derive(Clone, PartialEq, Eq, Debug)]
    pub struct Plan {
        pub key: cache::Key,
        pub identity: Identity,
        pub expected: Vec<Expected>,
        pub reproducibility: Reproducibility,
    }

    impl Plan {
        pub fn key_for(identity: &Identity, request: &Request) -> cache::Key {
            let mut record = crate::canonical::Record::new();
            record
                .record("identity", &identity.canonical())
                .record("request", &request.canonical());
            cache::Key::from_digest(record.to_digest())
        }

        pub fn write_json(&self, w: &mut Writer, key: &str) {
            w.begin_object(Some(key));
            w.field_str("key", &self.key.to_hex());
            w.field_str("reproducibility", self.reproducibility.as_str());
            self.identity.write_json(w, "identity");
            w.begin_array(Some("expected"));
            for one in &self.expected {
                w.begin_object(None);
                w.field_str("name", &one.name);
                w.field_str("kind", one.kind.as_str());
                w.end_object();
            }
            w.end_array();
            w.end_object();
        }
    }

    #[derive(Clone, Debug)]
    pub struct Budget {
        pub seconds: u64,
        pub output_bytes: u64,
        cancelled: Arc<AtomicBool>,
    }

    impl Budget {
        pub fn of(seconds: u64, output_bytes: u64) -> Budget {
            Budget {
                seconds,
                output_bytes,
                cancelled: Arc::new(AtomicBool::new(false)),
            }
        }

        pub fn stopper(&self) -> Stopper {
            Stopper {
                flag: Arc::clone(&self.cancelled),
            }
        }

        pub fn is_cancelled(&self) -> bool {
            self.cancelled.load(Ordering::Relaxed)
        }
    }

    impl Default for Budget {
        fn default() -> Budget {
            Budget::of(300, 512 * 1024 * 1024)
        }
    }

    #[derive(Clone, Debug)]
    pub struct Stopper {
        flag: Arc<AtomicBool>,
    }

    impl Stopper {
        pub fn stop(&self) {
            self.flag.store(true, Ordering::Relaxed);
        }
    }

    #[derive(Clone, PartialEq, Eq, Debug)]
    pub struct Produced {
        pub name: String,
        pub kind: Kind,
        pub digest: Digest,
        pub bytes: u64,
    }

    #[derive(Clone, Debug)]
    pub struct Compiled {
        pub key: cache::Key,
        pub identity: Identity,
        pub produced: Vec<Produced>,
        pub reproducibility: Reproducibility,
    }

    impl Compiled {
        pub fn write_json(&self, w: &mut Writer, key: &str) {
            w.begin_object(Some(key));
            w.field_str("key", &self.key.to_hex());
            w.field_str("reproducibility", self.reproducibility.as_str());
            self.identity.write_json(w, "identity");
            w.begin_array(Some("produced"));
            for one in &self.produced {
                w.begin_object(None);
                w.field_str("name", &one.name);
                w.field_str("kind", one.kind.as_str());
                w.field_str("digest", &one.digest.to_hex());
                w.field_u64("bytes", one.bytes);
                w.end_object();
            }
            w.end_array();
            w.end_object();
        }
    }

    pub struct Session<'a> {
        origin: &'static str,
        store: &'a Store,
        policy: &'a mut Policy,
        diagnostics: &'a mut Sink,
        budget: Budget,
        started: std::time::Instant,
        offered: Vec<(String, Kind, Vec<u8>)>,
        spent: u64,
    }

    impl<'a> Session<'a> {
        pub fn new(
            origin: &'static str,
            store: &'a Store,
            policy: &'a mut Policy,
            diagnostics: &'a mut Sink,
            budget: Budget,
        ) -> Session<'a> {
            Session {
                origin,
                store,
                policy,
                diagnostics,
                budget,
                started: std::time::Instant::now(),
                offered: Vec::new(),
                spent: 0,
            }
        }

        pub fn store(&self) -> &Store {
            self.store
        }

        pub fn budget(&self) -> &Budget {
            &self.budget
        }

        pub fn require(&mut self, capability: Capability) -> Decision {
            self.policy.request(self.origin, capability)
        }

        pub fn report(&mut self, diagnostic: Diagnostic) {
            self.diagnostics.emit(diagnostic);
        }

        pub fn carry_on(&self) -> Result<(), Diagnostic> {
            if self.budget.is_cancelled() {
                return Err(Diagnostic::new(
                    "EX001",
                    Severity::Warning,
                    FailureClass::UserError,
                    self.origin,
                    "The compilation was stopped.",
                )
                .with_suggestion(
                    "Nothing it had produced was published, so nothing downstream can \
                     read half of it.",
                ));
            }
            let spent = self.started.elapsed().as_secs();
            if spent > self.budget.seconds {
                return Err(fail(
                    self.origin,
                    "EX002",
                    "The compilation ran past the time it was given.",
                )
                .with_context(format!("Spent: {spent} seconds"))
                .with_context(format!("Allowed: {} seconds", self.budget.seconds))
                .with_suggestion(
                    "Nothing it had produced was published. A build on a device shares \
                     that device with whatever the person is actually doing.",
                ));
            }
            Ok(())
        }

        pub fn offer(
            &mut self,
            name: impl Into<String>,
            kind: Kind,
            bytes: Vec<u8>,
        ) -> Result<(), Diagnostic> {
            self.carry_on()?;
            let name = name.into();
            if self.offered.iter().any(|(held, _, _)| *held == name) {
                return Err(fail(
                    self.origin,
                    "EX003",
                    "One compilation offered two things under one name.",
                )
                .with_context(format!("Name: {name}")));
            }
            self.spent += bytes.len() as u64;
            if self.spent > self.budget.output_bytes {
                return Err(fail(
                    self.origin,
                    "EX004",
                    "The compilation produced more than it was allowed to.",
                )
                .with_context(format!("Produced: {} bytes", self.spent))
                .with_context(format!("Allowed: {} bytes", self.budget.output_bytes)));
            }
            self.offered.push((name, kind, bytes));
            Ok(())
        }

        pub fn offered(&self) -> usize {
            self.offered.len()
        }

        pub fn commit(self, plan: &Plan) -> Result<Compiled, Diagnostic> {
            if plan.expected.len() != self.offered.len() {
                return Err(fail(
                    self.origin,
                    "EX005",
                    "The compilation did not produce what it planned to.",
                )
                .with_context(format!("Planned: {} outputs", plan.expected.len()))
                .with_context(format!("Produced: {} outputs", self.offered.len()))
                .with_suggestion(
                    "A plan is a promise about what will exist. Nothing is published \
                     from a compilation that did not keep it.",
                ));
            }

            let mut produced = Vec::with_capacity(self.offered.len());
            for (name, kind, bytes) in &self.offered {
                let promised = plan.expected.iter().find(|one| one.name == *name);
                let Some(promised) = promised else {
                    return Err(fail(
                        self.origin,
                        "EX006",
                        "The compilation produced something it never planned to.",
                    )
                    .with_context(format!("Name: {name}")));
                };
                if promised.kind != *kind {
                    return Err(fail(
                        self.origin,
                        "EX007",
                        "The compilation produced something other than what it planned.",
                    )
                    .with_context(format!("Name: {name}"))
                    .with_context(format!("Planned: {}", promised.kind.as_str()))
                    .with_context(format!("Produced: {}", kind.as_str())));
                }

                let digest = self.store.put(bytes)?;
                let back = self.store.get(digest)?;
                if back != *bytes {
                    return Err(Diagnostic::new(
                        "EX008",
                        Severity::Fatal,
                        FailureClass::Corruption,
                        self.origin,
                        "What was stored is not what was compiled.",
                    )
                    .with_context(format!("Name: {name}")));
                }
                produced.push(Produced {
                    name: name.clone(),
                    kind: *kind,
                    digest,
                    bytes: bytes.len() as u64,
                });
            }

            produced.sort_by(|left, right| left.name.cmp(&right.name));
            Ok(Compiled {
                key: plan.key,
                identity: plan.identity.clone(),
                produced,
                reproducibility: plan.reproducibility.clone(),
            })
        }
    }

    impl std::fmt::Debug for Session<'_> {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(
                f,
                "Session {{ origin: {}, offered: {} }}",
                self.origin,
                self.offered.len()
            )
        }
    }

    pub trait Compiler: Sync {
        fn contract(&self) -> &'static Contract;

        fn probe(&self) -> Probe;

        fn plan(&self, request: &Request) -> Result<Plan, Diagnostic>;

        fn compile(
            &self,
            plan: &Plan,
            request: &Request,
            session: Session<'_>,
        ) -> Result<Compiled, Diagnostic>;
    }

    pub fn check_contract(compiler: &dyn Compiler) -> Vec<String> {
        let contract = compiler.contract();
        let mut wrong = Vec::new();

        if contract.id.is_empty() || !contract.id.starts_with("omni.plugin.") {
            wrong.push(format!(
                "{}: an id must be omni.plugin.something",
                contract.id
            ));
        }
        for required in contract.required_capabilities {
            if contract.forbidden_capabilities.contains(required) {
                wrong.push(format!(
                    "{}: {} is both required and forbidden",
                    contract.id,
                    required.as_str()
                ));
            }
        }
        if contract.outputs.is_empty() {
            wrong.push(format!(
                "{}: a compiler that outputs nothing is not one",
                contract.id
            ));
        }
        if contract.non_responsibilities.is_empty() {
            wrong.push(format!(
                "{}: what a compiler does not do is part of what it is",
                contract.id
            ));
        }

        let probe = compiler.probe();
        match (&probe.identity, &probe.unavailable) {
            (Some(_), Some(_)) => wrong.push(format!(
                "{}: a probe cannot be both usable and unavailable",
                contract.id
            )),
            (None, None) => wrong.push(format!(
                "{}: a probe that found nothing has to say why",
                contract.id
            )),
            _ => {}
        }
        if let Some(identity) = &probe.identity {
            if identity.version.is_empty() {
                wrong.push(format!(
                    "{}: an identity without a version is not one",
                    contract.id
                ));
            }
            if contract.produces_artifacts && identity.language.is_empty() {
                wrong.push(format!(
                    "{}: an identity has to name its language",
                    contract.id
                ));
            }
        }

        let request = Request::new(Abi::Arm64V8a, OLDEST_API)
            .with_source(Source::of("probe.txt", b"anything at all"));
        if let (Ok(first), Ok(again)) = (compiler.plan(&request), compiler.plan(&request)) {
            if first.key != again.key {
                wrong.push(format!(
                    "{}: planning the same request twice gave two keys",
                    contract.id
                ));
            }
            if first.identity.digest() != again.identity.digest() {
                wrong.push(format!(
                    "{}: an identity that moves is not one",
                    contract.id
                ));
            }
        }

        let other = Request::new(Abi::Arm64V8a, NEWEST_API)
            .with_source(Source::of("probe.txt", b"anything at all"));
        if let (Ok(first), Ok(second)) = (compiler.plan(&request), compiler.plan(&other)) {
            if first.key == second.key {
                wrong.push(format!(
                    "{}: two platforms planned to the same key",
                    contract.id
                ));
            }
        }

        wrong
    }
}

