    #[no_mangle]
    pub unsafe extern "C" fn omni_build_all(
        root: *const c_char,
        package_path: *const c_char,
        bundle_path: *const c_char,
        key_path: *const c_char,
        key_password: *const c_char,
    ) -> *mut c_char {
        let result = catch_unwind(|| {
            let (Some(root), Some(package_path), Some(bundle_path), Some(key_path)) = (
                text_from(root),
                text_from(package_path),
                text_from(bundle_path),
                text_from(key_path),
            ) else {
                return std::ptr::null_mut();
            };
            let password = text_from(key_password).unwrap_or_default();

            let mut w = crate::json::Writer::new();
            w.begin_object(None);

            crate::progress::begin();
            let mut sink = crate::diag::Sink::new();
            let now = now_seconds();

            let outcome = (|| {
                let (key, certificate) = signing_pair(&key_path, &password, now, &mut w)?;
                let made_by = crate::builder::made_by(&certificate)?;
                let project = crate::builder::sealed_project(&root, Some(&made_by))?;
                w.field_bool("carriesImage", project.icon.is_some());
                w.field_bool("sealed", project.sealed.is_some());
                w.field_u64("locales", project.values.len() as u64);
                let package = crate::builder::assemble(&project, &key, &certificate, &mut sink)?;
                let bundle = crate::bundle::write(&project)?;
                Ok((package, bundle))
            })();

            #[allow(unused_assignments)]
            let mut built = false;
            match outcome {
                Ok((package, bundle)) => {
                    match write_both(
                        &package_path,
                        &package.package,
                        &bundle_path,
                        &bundle.bundle,
                    ) {
                        Ok(()) => {
                            built = true;
                            w.field_bool("built", true);
                            w.field_str("path", &package_path);
                            w.field_str("bundlePath", &bundle_path);
                            match write_side_signature(&package_path, &package.side_signature) {
                                Some(beside) => w.field_str("sideSignaturePath", &beside),
                                None => w.field_str("sideSignaturePath", ""),
                            }
                            package.write_json(&mut w, "package");
                            bundle.write_json(&mut w, "bundle");
                        }
                        Err(why) => {
                            w.field_bool("built", false);
                            w.field_str(
                                "error",
                                &format!("what was built could not be written: {why}"),
                            );
                        }
                    }
                }
                Err(error) => write_failure(&mut w, "built", &error),
            }

            crate::progress::finish(built);
            w.field_str("timings", &crate::progress::timings());
            sink.write_json(&mut w, "diagnostics");
            w.end_object();
            hand_back(w)
        });
        result.unwrap_or(std::ptr::null_mut())
    }

