    #[test]
    fn a_refusal_is_written_in_the_language_the_reader_asked_for() {
        let _turn = super::progress::one_at_a_time();
        let refusal = Diagnostic::new(
            "EY013",
            Severity::Error,
            FailureClass::UserError,
            "core.keystore",
            "The validity period is outside what a certificate may carry.",
        )
        .with_context("Chosen: 20000 days")
        .with_context("Allowed: 30 to 9125 days")
        .with_suggestion("Google Play requires a key valid until at least 22 October 2033.");

        assert_eq!(super::speech::choose("en"), "en");
        let mut w = super::json::Writer::new();
        refusal.write_json(&mut w);
        let english = w.finish();
        assert!(
            english.contains("The validity period is outside"),
            "{english}"
        );
        assert!(english.contains("Chosen: 20000 days"), "{english}");

        assert_eq!(super::speech::choose("tr-TR"), "tr");
        let mut w = super::json::Writer::new();
        refusal.write_json(&mut w);
        let turkish = w.finish();
        super::speech::choose("en");

        assert!(
            turkish.contains("Geçerlilik süresi, bir sertifikanın taşıyabileceğinin dışında."),
            "{turkish}"
        );
        assert!(turkish.contains("Seçilen: 20000 days"), "{turkish}");
        assert!(
            turkish.contains("İzin verilen: 30 to 9125 days"),
            "{turkish}"
        );
        assert!(
            turkish.contains("Google Play, en az 22 Ekim 2033"),
            "{turkish}"
        );
        assert!(
            turkish.contains("The validity period is outside what a certificate may carry."),
            "the English is kept beside it: {turkish}"
        );
        assert_eq!(super::speech::chosen(), "en");
    }

    #[test]
    fn the_body_the_app_reads_is_written_in_the_chosen_language() {
        let _turn = super::progress::one_at_a_time();
        let refusal = Diagnostic::new(
            "EM001",
            Severity::Error,
            FailureClass::UserError,
            "core.manifest",
            "The manifest could not be read.",
        )
        .with_context("Path: /a/b");

        super::speech::choose("tr");
        let mut w = super::json::Writer::new();
        w.begin_object(None);
        refusal.write_body(&mut w, "created", false);
        w.end_object();
        let body = w.finish();
        super::speech::choose("en");

        assert!(
            body.contains("Bildirim okunamadı."),
            "the error the app reads is translated: {body}"
        );
        assert!(body.contains("Yol: /a/b"), "the context labels too: {body}");
        assert!(
            body.contains("\"english\""),
            "the English is carried alongside for the log: {body}"
        );
    }

    #[test]
    fn every_language_the_interface_offers_answers_in_its_own_words() {
        let _turn = super::progress::one_at_a_time();
        let refusal = Diagnostic::new(
            "EM001",
            Severity::Error,
            FailureClass::UserError,
            "core.manifest",
            "The manifest could not be read.",
        )
        .with_context("Path: /a/b");

        for spoken in super::speech::LANGUAGES {
            assert_eq!(super::speech::choose(spoken), *spoken);
            let sentence = super::speech::sentence("The manifest could not be read.");
            let label = super::speech::detail("Path: /a/b");
            let mut w = super::json::Writer::new();
            refusal.write_json(&mut w);
            let written = w.finish();
            assert!(written.contains(&sentence), "{spoken}: {written}");
            assert!(written.contains(&label), "{spoken}: {written}");
            assert!(
                written.contains("The manifest could not be read."),
                "the English is kept beside it: {spoken}: {written}"
            );
            if *spoken != "en" {
                assert_ne!(sentence, "The manifest could not be read.", "{spoken}");
                assert_ne!(label, "Path: /a/b", "{spoken}");
            }
        }

        assert_eq!(super::speech::choose("zh-Hans"), "zh");
        assert_eq!(
            super::speech::sentence("The manifest could not be read."),
            "无法读取清单。"
        );
        assert_eq!(super::speech::choose("en"), "en");
    }

