    const WHAT_JAVAC_WRITES: &str = r####"
package com.my.app;

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

@Written.Tagged(
    value = "the class",
    order = 3,
    of = String.class,
    kind = Written.Kind.FANCY,
    also = {"a", "b"},
    small = 7,
    wide = 9223372036854775807L,
    exact = 0.5,
    rough = 1.5f,
    letter = 'q',
    flag = true)
public class Written {
    @Retention(RetentionPolicy.RUNTIME)
    @Target({ElementType.TYPE, ElementType.FIELD, ElementType.METHOD, ElementType.PARAMETER})
    public @interface Tagged {
        String value();

        int order() default 1;

        Class<?> of() default Object.class;

        Kind kind() default Kind.PLAIN;

        String[] also() default {};

        byte small() default 0;

        long wide() default 0L;

        double exact() default 0.0;

        float rough() default 0.0f;

        char letter() default 'a';

        boolean flag() default false;
    }

    public enum Kind {
        PLAIN,
        FANCY
    }

    @Tagged("a field")
    static String label;

    @Tagged("a method")
    public static int marked(@Tagged("a parameter") int by) {
        return by + 1;
    }

    int count;
    long total;
    static int[][] grid;
    static String[][][] words;

    public static int[][] make(int rows, int columns) {
        return new int[rows][columns];
    }

    public static int[][] partly(int rows) {
        return new int[rows][];
    }

    public static String[][][] deep(int a, int b) {
        words = new String[a][b][];
        return words;
    }

    public int stepped() {
        // The result of a compound assignment on a field, which javac writes
        // with dup_x1.
        return (count += 1);
    }

    public long stepped_wide() {
        return (total += 2L);
    }

    public static int inside(int[] held, int at) {
        return (held[at] += 3);
    }

    public static long inside_wide(long[] held, int at) {
        return (held[at] += 4L);
    }

    public static int chained() {
        int a;
        int b;
        a = b = 7;
        return a + b;
    }

    public static String joined(int a, long b, double c, Object d, String e, char f, boolean g) {
        return "a=" + a + " b=" + b + " c=" + c + " d=" + d + " e=" + e + " f=" + f + " g=" + g + "!";
    }

    public static String joined_only_values(String a, String b) {
        return a + b;
    }

    public static String describe(int which) {
        String out;
        switch (which) {
            case 1:
                out = "one";
                break;
            case 2:
                out = "two";
                break;
            default:
                out = "many";
        }
        try {
            return out.concat(String.valueOf(which));
        } finally {
            out = null;
        }
    }

    public interface Named {
        String of(int which);
    }

    public interface Counted {
        int count(String what);
    }

    public interface Made {
        Object make(String from);
    }

    public interface Boxed {
        Object of(long value);
    }

    public interface Taken {
        long of(Object value);
    }

    public static Named plain() {
        return which -> "n" + which;
    }

    public Named capturing(String prefix, int step) {
        return which -> prefix + (which + step) + count;
    }

    public Named bound() {
        return this::named;
    }

    private String named(int which) {
        return "b" + which + count;
    }

    public static Counted lengths() {
        return String::length;
    }

    public static Made makers() {
        return StringBuilder::new;
    }

    public static Boxed boxing() {
        return Long::valueOf;
    }

    public static Taken taking() {
        return value -> ((Long) value).longValue();
    }

    // A generic interface, whose method is erased to Object in and Object out:
    // the value has to be cast on the way in and boxed on the way out.
    public static java.util.function.Function<String, Integer> erased() {
        return String::length;
    }

    public static java.util.function.Supplier<String> supplying(String held) {
        return () -> held + "!";
    }

    public static java.util.function.BiFunction<Long, Long, Long> adding() {
        return Long::sum;
    }

    public static int many(int seed) {
        int a0 = seed, a1 = a0 + 1, a2 = a1 + 1, a3 = a2 + 1, a4 = a3 + 1;
        int a5 = a4 + 1, a6 = a5 + 1, a7 = a6 + 1, a8 = a7 + 1, a9 = a8 + 1;
        long b0 = a9, b1 = b0 + 1, b2 = b1 + 1, b3 = b2 + 1, b4 = b3 + 1;
        double c0 = b4, c1 = c0 + 1, c2 = c1 + 1, c3 = c2 + 1, c4 = c3 + 1;
        Object d0 = null, d1 = d0, d2 = d1, d3 = d2, d4 = d3;
        return a0 + a1 + a2 + a3 + a4 + a5 + a6 + a7 + a8 + a9
            + (int) (b0 + b1 + b2 + b3 + b4)
            + (int) (c0 + c1 + c2 + c3 + c4)
            + (d0 == d4 ? 1 : 0);
    }
}
"####;

    #[test]
    fn what_another_compiler_writes_translates_and_holds_up() {
        let directory = temp_directory("omni-javac");
        let out = directory.join("out");
        std::fs::create_dir_all(&out).unwrap();
        let source = directory.join("Written.java");
        std::fs::write(&source, WHAT_JAVAC_WRITES.trim_start()).unwrap();

        let done = std::process::Command::new("javac")
            .args(["--release", "17", "-d"])
            .arg(out.to_str().unwrap())
            .arg(source.to_str().unwrap())
            .output();
        let Ok(done) = done else {
            std::fs::remove_dir_all(&directory).ok();
            assert!(
                std::env::var("OMNI_REQUIRE_JAVAC").is_err(),
                "OMNI_REQUIRE_JAVAC is set but javac is not here"
            );
            eprintln!("javac conformance: javac is not available here");
            return;
        };
        assert!(
            done.status.success(),
            "javac refused its own source: {}",
            String::from_utf8_lossy(&done.stderr)
        );

        let mut written = Vec::new();
        gather_class_files(&out, &mut written);
        written.sort();
        assert!(!written.is_empty(), "javac wrote nothing");

        let mut refused = Vec::new();
        let mut joined = 0;
        let mut every: Vec<crate::dexwrite::Class> = Vec::new();
        for path in &written {
            let bytes = std::fs::read(path).unwrap();
            let class = crate::jvm::read(&bytes)
                .unwrap_or_else(|error| panic!("{} does not read: {error:?}", path.display()));
            let translated = crate::dalvik::translate_class(&class)
                .unwrap_or_else(|error| panic!("{} does not translate: {error:?}", path.display()));
            for one in &translated {
                refused.extend(what_the_runtime_would_refuse(one));
            }
            every.extend(translated.iter().cloned());

            for method in translated
                .iter()
                .flat_map(|one| one.direct_methods.iter().chain(one.virtual_methods.iter()))
            {
                let wanted: &[&str] = match method.reference.name.as_str() {
                    "joined" => &[
                        "\"a=\"",
                        "Ljava/lang/String;",
                        "I",
                        "\" b=\"",
                        "Ljava/lang/String;",
                        "J",
                        "\" c=\"",
                        "Ljava/lang/String;",
                        "D",
                        "\" d=\"",
                        "Ljava/lang/String;",
                        "Ljava/lang/String;",
                        "\" e=\"",
                        "Ljava/lang/String;",
                        "Ljava/lang/String;",
                        "\" f=\"",
                        "Ljava/lang/String;",
                        "C",
                        "\" g=\"",
                        "Ljava/lang/String;",
                        "Z",
                        "\"!\"",
                        "Ljava/lang/String;",
                    ],
                    "joined_only_values" => &["Ljava/lang/String;", "Ljava/lang/String;"],
                    _ => continue,
                };
                assert_eq!(
                    pieces_of(method),
                    wanted,
                    "{} is not joined the way it was written",
                    method.reference.name
                );
                joined += 1;
            }
        }
        assert!(
            refused.is_empty(),
            "the runtime would refuse this:\n  {}",
            refused.join("\n  ")
        );
        assert_eq!(joined, 2, "both joined strings were read");

        let names: Vec<&str> = every
            .iter()
            .map(|one| one.descriptor.as_str())
            .filter(|one| one.contains("$$Lambda$"))
            .collect();
        assert!(
            names.len() >= 10,
            "a lambda for each one written: {names:?}"
        );

        let by_interface = |wanted: &str| -> &crate::dexwrite::Class {
            every
                .iter()
                .find(|one| one.interfaces.iter().any(|held| held == wanted))
                .unwrap_or_else(|| panic!("nothing implements {wanted}"))
        };

        let counted = by_interface("Lcom/my/app/Written$Counted;");
        assert!(
            counted.instance_fields.is_empty(),
            "a method reference that captured nothing keeps nothing"
        );
        let count = counted
            .virtual_methods
            .iter()
            .find(|one| one.reference.name == "count")
            .expect("it has the interface's method");
        assert_eq!(count.reference.parameters, vec!["Ljava/lang/String;"]);
        assert_eq!(count.reference.return_type, "I");

        let erased = by_interface("Ljava/util/function/Function;");
        let apply = erased
            .virtual_methods
            .iter()
            .find(|one| one.reference.name == "apply")
            .expect("it has the interface's method");
        assert_eq!(apply.reference.parameters, vec!["Ljava/lang/Object;"]);
        assert_eq!(apply.reference.return_type, "Ljava/lang/Object;");
        let told: Vec<String> = apply
            .instructions
            .iter()
            .filter_map(|one| match &one.operand {
                crate::dexwrite::Operand::Type(descriptor) => Some(format!("cast {descriptor}")),
                crate::dexwrite::Operand::Method(call) => {
                    Some(format!("{}.{}", call.class, call.name))
                }
                _ => None,
            })
            .collect();
        assert_eq!(
            told,
            vec![
                "cast Ljava/lang/String;",
                "Ljava/lang/String;.length",
                "Ljava/lang/Integer;.valueOf",
            ],
            "the value is cast on the way in and boxed on the way out"
        );

        let dex = crate::dexwrite::write(&every, &[]).expect("the dex is written");
        if let Some((_, held)) = dexdump(&dex) {
            for one in &names {
                assert!(
                    held.iter().any(|found| found == one),
                    "{one} is not in the package: {held:?}"
                );
            }
        }

        let mut told = annotations_in(&dex, "Lcom/my/app/Written;");
        told.sort();
        assert_eq!(
            told,
            vec![
                "class seen Lcom/my/app/Written$Tagged;(also=[text \"a\", text \"b\"], \
                 exact=double 0.5, flag=boolean true, \
                 kind=enum Lcom/my/app/Written$Kind;.FANCY, letter=char 113, \
                 of=class Ljava/lang/String;, order=int 3, rough=float 1.5, \
                 small=byte 7, value=text \"the class\", wide=long 9223372036854775807)",
                "class system Ldalvik/annotation/MemberClasses;(value=[\
                 class Lcom/my/app/Written$Named;, class Lcom/my/app/Written$Counted;, \
                 class Lcom/my/app/Written$Made;, class Lcom/my/app/Written$Boxed;, \
                 class Lcom/my/app/Written$Taken;, class Lcom/my/app/Written$Kind;, \
                 class Lcom/my/app/Written$Tagged;])",
                "field Lcom/my/app/Written;.label seen \
                 Lcom/my/app/Written$Tagged;(value=text \"a field\")",
                "method seen Lcom/my/app/Written$Tagged;(value=text \"a method\")",
                "method system Ldalvik/annotation/Signature;(value=[text \
                 \"()Ljava/util/function/BiFunction<Ljava/lang/Long;Ljava/lang/Long;\
                 Ljava/lang/Long;>;\"])",
                "method system Ldalvik/annotation/Signature;(value=[text \
                 \"()Ljava/util/function/Function<Ljava/lang/String;Ljava/lang/Integer;>;\"])",
                "method system Ldalvik/annotation/Signature;(value=[text \
                 \"(Ljava/lang/String;)Ljava/util/function/Supplier<Ljava/lang/String;>;\"])",
                "parameter seen Lcom/my/app/Written$Tagged;(value=text \"a parameter\")",
            ],
            "the package does not say what was written on the class"
        );

        let mut nested = annotations_in(&dex, "Lcom/my/app/Written$Tagged;");
        nested.sort();
        assert_eq!(
            nested,
            vec![
                "class seen Ljava/lang/annotation/Retention;(value=enum \
                 Ljava/lang/annotation/RetentionPolicy;.RUNTIME)",
                "class seen Ljava/lang/annotation/Target;(value=[enum \
                 Ljava/lang/annotation/ElementType;.TYPE, enum \
                 Ljava/lang/annotation/ElementType;.FIELD, enum \
                 Ljava/lang/annotation/ElementType;.METHOD, enum \
                 Ljava/lang/annotation/ElementType;.PARAMETER])",
                "class system Ldalvik/annotation/AnnotationDefault;(value=\
                 Lcom/my/app/Written$Tagged;(also=[], exact=double 0, flag=boolean false, \
                 kind=enum Lcom/my/app/Written$Kind;.PLAIN, letter=char 97, \
                 of=class Ljava/lang/Object;, order=int 1, rough=float 0, small=byte 0, \
                 wide=long 0))",
                "class system Ldalvik/annotation/EnclosingClass;(value=class \
                 Lcom/my/app/Written;)",
                "class system Ldalvik/annotation/InnerClass;(accessFlags=int 9737, \
                 name=text \"Tagged\")",
                "method system Ldalvik/annotation/Signature;(value=[text \
                 \"()Ljava/lang/Class<*>;\"])",
            ],
            "the annotation type does not say what it is"
        );

        let mut wanted: Vec<u32> = Vec::new();
        for path in &written {
            let bytes = std::fs::read(path).unwrap();
            let class = crate::jvm::read(&bytes).unwrap();
            for method in &class.methods {
                let Some(code) = &method.code else { continue };
                wanted.extend(code.lines.iter().map(|(_, line)| u32::from(*line)));
            }
        }
        wanted.sort();
        wanted.dedup();
        assert!(wanted.len() > 20, "javac wrote {} lines down", wanted.len());
        if let Some(said) = dexdump_text(&dex) {
            let mut found: Vec<u32> = said
                .lines()
                .filter_map(|line| line.split("line=").nth(1))
                .filter_map(|held| held.trim().parse::<u32>().ok())
                .collect();
            found.sort();
            found.dedup();
            assert_eq!(
                found, wanted,
                "the package does not say the lines the class files said"
            );
        }
        std::fs::remove_dir_all(&directory).ok();
        eprintln!(
            "javac conformance: {} classes another compiler wrote translate and hold up",
            written.len()
        );
    }

    fn pieces_of(method: &crate::dexwrite::Method) -> Vec<String> {
        let mut out = Vec::new();
        for one in &method.instructions {
            match &one.operand {
                crate::dexwrite::Operand::Text(text) => out.push(format!("{text:?}")),
                crate::dexwrite::Operand::Method(call) if call.name == "append" => {
                    out.push(call.parameters.join(","))
                }
                _ => {}
            }
        }
        out
    }

