    #[test]
    fn a_qualifier_this_build_does_not_model_is_refused() {
        let mut table = ResourceTable::new();
        let mut sink = Sink::new();
        assert!(!table.read_file(
            "drawable-nonsuch",
            "a.png",
            "res/drawable-nonsuch/a.png",
            &mut sink
        ));
        let error = sink.entries().iter().find(|d| d.code == "E9010").unwrap();
        assert!(
            error.message.contains("does not model"),
            "{}",
            error.message
        );

        let mut sink = Sink::new();
        assert!(
            table.read_file("drawable-tr", "a.png", "res/drawable-tr/a.png", &mut sink),
            "a language is a qualifier this build does model"
        );

        let mut sink = Sink::new();
        assert!(
            table.read_file(
                "drawable-sw600dp-land-night-xxhdpi-v31",
                "b.png",
                "res/drawable-sw600dp-land-night-xxhdpi-v31/b.png",
                &mut sink
            ),
            "{:?}",
            sink.entries()
        );

        for wrong in [
            "drawable-night-land",
            "drawable-v31-xxhdpi",
            "drawable-land-sw600dp",
            "drawable-navhidden-nokeys",
            "drawable-land-port",
        ] {
            let mut sink = Sink::new();
            assert!(
                !table.read_file(wrong, "c.png", &format!("res/{wrong}/c.png"), &mut sink),
                "{wrong} is an order the platform does not read"
            );
            let error = sink.entries().iter().find(|d| d.code == "E9010").unwrap();
            assert!(
                error.message.contains("order the platform does not read"),
                "{}",
                error.message
            );
        }

        for right in [
            "drawable-land-night",
            "drawable-xxhdpi-v31",
            "drawable-sw600dp-land",
            "drawable-nokeys-navhidden",
            "drawable-en-rGB-w600dp",
        ] {
            let mut sink = Sink::new();
            assert!(
                table.read_file(right, "d.png", &format!("res/{right}/d.png"), &mut sink),
                "{right}: {:?}",
                sink.entries()
            );
        }

        let mut sink = Sink::new();
        assert!(!table.read_file("nonsense", "a.png", "res/nonsense/a.png", &mut sink));
        let error = sink.entries().iter().find(|d| d.code == "E9010").unwrap();
        assert!(
            error.message.contains("is not a resource type"),
            "{}",
            error.message
        );
    }

