    #[test]
    fn changing_one_byte_of_a_dex_is_reported_but_not_hidden() {
        let mut data = minimal_dex(b"035");
        data[dex::HEADER_SIZE as usize - 1] ^= 0xff;

        let mut sink = Sink::new();
        let file = dex::read(&data, &mut sink);
        assert!(file.is_ok(), "a damaged DEX still reads");

        let codes: Vec<&str> = sink.entries().iter().map(|d| d.code.as_str()).collect();
        assert!(codes.contains(&"EX020"), "checksum: {codes:?}");
        assert!(codes.contains(&"EX021"), "signature: {codes:?}");

        let integrity = dex::integrity(&data).unwrap();
        assert!(!integrity.self_consistent());
    }

    #[test]
    fn integrity_is_never_reported_as_more_than_it_is() {
        let data = minimal_dex(b"035");
        let integrity = dex::integrity(&data).unwrap();

        let mut w = Writer::new();
        w.begin_object(None);
        integrity.write_json(&mut w, "integrity");
        w.end_object();
        let document = w.finish();

        assert!(is_structurally_valid(&document));
        assert!(document.contains("\"checksumMatches\":true"));
        assert!(document.contains("not evidence of authorship or authenticity"));
        assert!(document.contains("SHA-1 is broken for collision resistance"));
    }

    #[test]
    fn type_descriptors_become_the_names_a_person_writes() {
        let cases = [
            ("Ljava/lang/String;", "java.lang.String"),
            ("Lcom/omni/builder/Builder;", "com.omni.builder.Builder"),
            ("V", "void"),
            ("I", "int"),
            ("J", "long"),
            ("Z", "boolean"),
            ("B", "byte"),
            ("S", "short"),
            ("C", "char"),
            ("F", "float"),
            ("D", "double"),
            ("[I", "int[]"),
            ("[[Ljava/lang/String;", "java.lang.String[][]"),
        ];
        for (descriptor, expected) in cases {
            assert_eq!(
                dex::descriptor_to_source(descriptor),
                expected,
                "{descriptor}"
            );
        }

        for odd in ["", "Ljava/lang/String", "Q", "L;x"] {
            assert_eq!(dex::descriptor_to_source(odd), odd, "{odd:?}");
        }
    }

    const WALKS_ITS_OWN_CODE: &str = r#"
package com.omni.probe;

public class Walk {
    private int taps;
    private static final String LABEL = "walk";

    public int classify(int value) {
        switch (value) {
            case 0: return 10;
            case 1: return 11;
            case 2: return 12;
            default: return -1;
        }
    }

    public String guarded(String text) {
        try {
            return text.substring(0, 2);
        } catch (IndexOutOfBoundsException e) {
            return LABEL;
        } finally {
            taps++;
        }
    }

    public String describe() {
        StringBuilder out = new StringBuilder();
        for (int one : counts()) {
            out.append(one);
            out.append(' ');
        }
        return LABEL + taps + " of " + out.toString();
    }

    private int[] counts() {
        int[] found = new int[3];
        for (int i = 0; i < found.length; i++) {
            found[i] = i * taps;
        }
        return found;
    }
}
"#;

    fn walked_dex() -> (Vec<crate::dexwrite::Class>, Vec<u8>) {
        let classpath = crate::compilers::java::Classpath::new();
        let mut written: Vec<crate::dexwrite::Class> = Vec::new();
        for (name, bytes) in
            crate::compilers::java::compile(WALKS_ITS_OWN_CODE, &classpath).expect("it compiles")
        {
            let class = crate::jvm::read(&bytes)
                .unwrap_or_else(|error| panic!("{name} does not read back: {error:?}"));
            written.extend(crate::dalvik::translate_class(&class).expect("it translates"));
        }
        let dex = crate::dexwrite::write(&written, &[]).expect("it writes");
        (written, dex)
    }

    #[test]
    fn every_instruction_this_build_writes_reads_back_as_the_one_it_wrote() {
        let (written, dex) = walked_dex();
        let mut sink = Sink::new();
        let read = dex::read(&dex, &mut sink).expect("it reads");
        assert!(
            !sink.entries().iter().any(|one| one.code == "EX038"),
            "every body must walk: {:?}",
            sink.entries()
        );
        assert!(!sink.has_blocking(), "{:?}", sink.entries());

        let mut checked = 0usize;
        let mut instructions = 0usize;
        for source in &written {
            let name = dex::descriptor_to_source(&source.descriptor);
            let held = read
                .class(&name)
                .unwrap_or_else(|| panic!("{name} is not in the file"));
            for method in source
                .direct_methods
                .iter()
                .chain(source.virtual_methods.iter())
            {
                let called = &method.reference.name;
                let body = held
                    .methods()
                    .find(|one| one.name == *called && one.shorty == method.reference.shorty())
                    .unwrap_or_else(|| panic!("{name}.{called} is not in the file"));
                if method.instructions.is_empty() {
                    assert!(
                        body.code.is_none(),
                        "{name}.{called} has code it did not write"
                    );
                    continue;
                }
                let code = body
                    .code
                    .as_ref()
                    .unwrap_or_else(|| panic!("{name}.{called} came back without a body"));
                let wanted: Vec<u8> = method
                    .instructions
                    .iter()
                    .map(|one| (one.units[0] & 0xff) as u8)
                    .collect();
                let got: Vec<u8> = code.instructions.iter().map(|one| one.opcode).collect();
                assert_eq!(got, wanted, "{name}.{called} does not read back");
                let widths: Vec<usize> =
                    method.instructions.iter().map(|one| one.width()).collect();
                let read_widths: Vec<usize> = code
                    .instructions
                    .iter()
                    .map(|one| one.units.len())
                    .collect();
                assert_eq!(
                    read_widths, widths,
                    "{name}.{called} is walked at the wrong stride"
                );
                assert_eq!(
                    code.registers, method.registers,
                    "{name}.{called} registers"
                );
                assert_eq!(code.inputs, method.inputs, "{name}.{called} inputs");
                assert_eq!(code.outputs, method.outputs, "{name}.{called} outputs");
                assert_eq!(
                    code.units as usize,
                    widths.iter().sum::<usize>(),
                    "{name}.{called} length"
                );
                checked += 1;
                instructions += got.len();
            }
        }
        assert!(checked >= 5, "only {checked} bodies were checked");
        assert!(
            instructions >= 60,
            "only {instructions} instructions were checked"
        );
        assert_eq!(read.instructions(), instructions);
        assert_eq!(read.bodies_read(), checked);
    }

    #[test]
    fn a_method_body_says_what_it_reaches_for() {
        let (_, dex) = walked_dex();
        let mut sink = Sink::new();
        let read = dex::read(&dex, &mut sink).expect("it reads");

        let describe = read
            .body("com.omni.probe.Walk", "describe")
            .expect("the class carries describe");
        let code = describe.code.as_ref().expect("with a body");
        let calls = code.calls();
        assert!(
            calls
                .iter()
                .any(|one| one.contains("java.lang.StringBuilder.append")),
            "the loop appends: {calls:?}"
        );
        assert!(
            calls
                .iter()
                .any(|one| one.contains("com.omni.probe.Walk.counts")),
            "and calls the method that makes the array: {calls:?}"
        );
        assert_eq!(describe.return_type, "java.lang.String");
        assert!(describe.parameters.is_empty());
        assert_eq!(describe.signature(), "describe() java.lang.String");

        let held: Vec<&str> = code
            .instructions
            .iter()
            .filter(|one| one.name.starts_with("const-string") || one.name.starts_with("sget"))
            .filter_map(|one| one.about.as_deref())
            .collect();
        assert!(
            held.contains(&"com.omni.probe.Walk.LABEL java.lang.String"),
            "the static it reads: {held:?}"
        );
        assert!(held.contains(&" of "), "and the text it holds: {held:?}");

        let counts = read
            .body("com.omni.probe.Walk", "counts")
            .expect("the class carries counts");
        let code = counts.code.as_ref().expect("with a body");
        assert_eq!(counts.return_type, "int[]");
        let touched: Vec<&str> = code
            .instructions
            .iter()
            .filter(|one| one.name.starts_with("iget") || one.name.starts_with("iput"))
            .filter_map(|one| one.about.as_deref())
            .collect();
        assert!(
            touched.contains(&"com.omni.probe.Walk.taps int"),
            "the field it reads: {touched:?}"
        );
        assert!(
            code.instructions.iter().any(|one| one.name == "new-array"),
            "and the array it makes:\n{}",
            code.to_text()
        );

        let classify = read
            .body("com.omni.probe.Walk", "classify")
            .expect("the class carries classify");
        let code = classify.code.as_ref().expect("with a body");
        assert!(
            code.instructions
                .iter()
                .any(|one| one.name == "packed-switch"),
            "a switch over three near values is packed:\n{}",
            code.to_text()
        );
        assert!(
            code.instructions
                .iter()
                .any(|one| one.name == "packed-switch-payload"),
            "and the table it points at is walked as one instruction:\n{}",
            code.to_text()
        );
        assert_eq!(classify.parameters, ["int"]);

        let guarded = read
            .body("com.omni.probe.Walk", "guarded")
            .expect("the class carries guarded");
        let code = guarded.code.as_ref().expect("with a body");
        assert!(!code.tries.is_empty(), "a try is a range the file records");
        let caught: Vec<String> = code
            .tries
            .iter()
            .flat_map(|one| one.catches.iter())
            .map(|one| one.kind.clone().unwrap_or_else(|| "everything".to_string()))
            .collect();
        assert!(
            caught
                .iter()
                .any(|one| one.contains("IndexOutOfBoundsException")),
            "what it catches: {caught:?}"
        );
        assert!(
            code.instructions
                .iter()
                .any(|one| one.name == "move-exception"),
            "and the handler starts by taking the exception:\n{}",
            code.to_text()
        );
    }

    #[test]
    fn every_opcode_has_a_name_and_a_stride() {
        let mut named = 0usize;
        for byte in 0..=255u8 {
            let shape = dex::shape_of(byte);
            let units = dex::units_of(shape.format);
            assert!(
                (1..=5).contains(&units),
                "0x{byte:02x} is {units} units wide"
            );
            assert!(!shape.name.is_empty());
            if shape.name != "unused" {
                named += 1;
            }
        }
        assert_eq!(named, 224, "the instruction set this reader knows");

        for (byte, name, units) in [
            (0x00u8, "nop", 1usize),
            (0x0e, "return-void", 1),
            (0x18, "const-wide", 5),
            (0x1a, "const-string", 2),
            (0x1b, "const-string/jumbo", 3),
            (0x6e, "invoke-virtual", 3),
            (0x74, "invoke-virtual/range", 3),
            (0xfa, "invoke-polymorphic", 4),
            (0xfb, "invoke-polymorphic/range", 4),
            (0xff, "const-method-type", 2),
        ] {
            let shape = dex::shape_of(byte);
            assert_eq!(shape.name, name, "0x{byte:02x}");
            assert_eq!(dex::units_of(shape.format), units, "0x{byte:02x}");
        }

        for gone in [0x3eu8, 0x43, 0x73, 0x79, 0x7a, 0xe3, 0xf9] {
            assert_eq!(dex::shape_of(gone).name, "unused", "0x{gone:02x}");
        }

        assert_eq!(dex::points_at(0x1a), dex::Points::Strings);
        assert_eq!(dex::points_at(0x22), dex::Points::Types);
        assert_eq!(dex::points_at(0x52), dex::Points::Fields);
        assert_eq!(dex::points_at(0x71), dex::Points::Methods);
        assert_eq!(dex::points_at(0xff), dex::Points::Prototypes);
        assert_eq!(dex::points_at(0x01), dex::Points::Nowhere);
    }

    #[test]
    fn a_body_that_cannot_be_walked_is_reported_where_it_is_rather_than_refusing_the_file() {
        let (_, dex) = walked_dex();
        let mut sink = Sink::new();
        let whole = dex::read(&dex, &mut sink).expect("it reads");
        let wanted = whole.bodies_read();
        assert!(wanted > 0);

        let mut bent = None;
        for at in 0..dex.len() - 1 {
            let mut copy = dex.clone();
            copy[at] ^= 0xff;
            let mut sink = Sink::new();
            let Ok(read) = dex::read(&copy, &mut sink) else {
                continue;
            };
            if sink.entries().iter().any(|one| one.code == "EX038") {
                bent = Some((read, sink));
                break;
            }
        }

        let (read, sink) = bent.expect("one flipped byte somewhere lands inside a body");
        let said = sink
            .entries()
            .iter()
            .find(|one| one.code == "EX038")
            .expect("the warning");
        assert_eq!(said.severity, Severity::Warning);
        assert!(
            said.context.iter().any(|line| line.starts_with("Method: ")),
            "the warning names the body it could not walk: {:?}",
            said.context
        );
        assert!(
            !read.class_names().is_empty(),
            "the rest of the file is still described"
        );
    }

    #[test]
    fn the_prototype_pool_carries_what_a_method_takes_as_well_as_what_it_returns() {
        let (_, dex) = walked_dex();
        let mut sink = Sink::new();
        let read = dex::read(&dex, &mut sink).expect("it reads");

        let held = read
            .methods
            .iter()
            .find(|one| one.class == "java.lang.String" && one.name == "substring")
            .expect("the file names String.substring");
        assert_eq!(held.parameters, ["int", "int"]);
        assert_eq!(held.return_type, "java.lang.String");
        assert_eq!(held.shorty, "LII");
        assert_eq!(
            held.signature(),
            "java.lang.String.substring(int, int) java.lang.String"
        );

        assert!(
            read.protos
                .iter()
                .any(|one| one.to_text() == "(int, int) java.lang.String"),
            "the prototype is in the pool in its own right"
        );

        let mut w = Writer::new();
        w.begin_object(None);
        read.write_json(&mut w, "dex");
        w.end_object();
        let document = w.finish();
        assert!(is_structurally_valid(&document), "{document}");
        assert!(document.contains("\"bodiesRead\":"));
        assert!(document.contains("\"instructions\":"));
    }

    #[test]
    fn modified_utf8_is_decoded_the_way_the_formats_define_it() {
        assert_eq!(modified_utf8::decode(b"Builder").unwrap(), "Builder");

        assert_eq!(modified_utf8::decode(&[0xc0, 0x80]).unwrap(), "\0");

        assert_eq!(modified_utf8::decode("çğü".as_bytes()).unwrap(), "çğü");
        assert_eq!(modified_utf8::decode("→".as_bytes()).unwrap(), "→");

        let rocket = [0xed, 0xa0, 0xbd, 0xed, 0xb2, 0x80];
        assert_eq!(modified_utf8::decode(&rocket).unwrap(), "\u{1f480}");

        assert!(modified_utf8::decode(&[0xf0, 0x9f, 0x92, 0x80]).is_err());
    }

    #[test]
    fn a_broken_string_is_refused_rather_than_repaired() {
        let cases: &[(&[u8], &str)] = &[
            (&[0xed, 0xa0, 0xbd], "E7053"),
            (&[0xed, 0xb2, 0x80], "E7053"),
            (&[0xc2], "E7050"),
            (&[0xe2, 0x86], "E7050"),
            (&[0xc2, 0x41], "E7051"),
            (&[0xf0, 0x9f, 0x92, 0x80], "E7052"),
        ];
        for (bytes, code) in cases {
            let error =
                modified_utf8::decode(bytes).expect_err(&format!("{bytes:?} must be refused"));
            assert_eq!(error.code, *code, "{bytes:?}");
        }
    }

    #[test]
    fn the_dex_reader_survives_arbitrary_input() {
        let mut seed = 0x1dea_7c0f_fee5_1234u64;
        for _ in 0..3_000 {
            let length = (xorshift(&mut seed) % 400) as usize;
            let mut data: Vec<u8> = (0..length)
                .map(|_| (xorshift(&mut seed) & 0xff) as u8)
                .collect();

            if length >= 8 && xorshift(&mut seed).is_multiple_of(2) {
                data[0..4].copy_from_slice(dex::MAGIC);
                data[4..8].copy_from_slice(b"035\0");
            }

            let mut sink = Sink::new();
            let _ = dex::read(&data, &mut sink);
            let _ = dex::integrity(&data);
            let _ = modified_utf8::decode(&data);
        }
    }

    fn dex_conformance_may_skip(why: &str) {
        assert!(
            std::env::var("OMNI_REQUIRE_DEX_CONFORMANCE").is_err(),
            "OMNI_REQUIRE_DEX_CONFORMANCE is set but the DEX conformance test \
             would have skipped: {why}"
        );
    }

    fn dex_this_build_produced() -> Option<Vec<u8>> {
        let Some(apk) = built_package() else {
            dex_conformance_may_skip("no APK has been built");
            return None;
        };

        let output = std::process::Command::new("unzip")
            .args(["-p", &apk.to_string_lossy(), "classes.dex"])
            .output()
            .ok()?;
        if !output.status.success() || output.stdout.is_empty() {
            dex_conformance_may_skip("classes.dex could not be read out of the APK");
            return None;
        }
        Some(output.stdout)
    }

    fn dexdump(bytes: &[u8]) -> Option<(std::collections::BTreeMap<String, String>, Vec<String>)> {
        let Some(tool) = find_apksigner().and_then(|p| Some(p.parent()?.join("dexdump"))) else {
            dex_conformance_may_skip("no Android SDK build-tools were found");
            return None;
        };
        if !tool.is_file() {
            dex_conformance_may_skip("dexdump is not in the build-tools found");
            return None;
        }

        let directory = temp_directory("dexdump");
        let path = directory.join("classes.dex");
        std::fs::write(&path, bytes).ok()?;

        let output = std::process::Command::new(&tool)
            .args(["-f", path.to_str()?])
            .output()
            .ok()?;
        std::fs::remove_dir_all(&directory).ok();
        if !output.status.success() {
            return None;
        }

        let text = String::from_utf8_lossy(&output.stdout).to_string();
        let mut fields = std::collections::BTreeMap::new();
        let mut classes = Vec::new();
        for line in text.lines() {
            let Some((left, right)) = line.split_once(':') else {
                continue;
            };
            let key = left.trim();
            let value = right.trim();
            if key == "Class descriptor" {
                classes.push(value.trim_matches('\'').to_string());
            } else if !key.contains(' ') || key.contains('_') || key == "magic" {
                fields.insert(key.to_string(), value.to_string());
            }
        }
        Some((fields, classes))
    }

    #[test]
    fn the_dex_this_build_produced_reads_as_dexdump_reads_it() {
        let Some(bytes) = dex_this_build_produced() else {
            eprintln!(
                "dex conformance: no built package here, so nothing was read. \
                 Build one with `./gradlew :Builder:assembleRelease`."
            );
            return;
        };
        let Some((fields, descriptors)) = dexdump(&bytes) else {
            eprintln!("dex conformance: dexdump is not available here");
            return;
        };

        let mut sink = Sink::new();
        let file = dex::read(&bytes, &mut sink).expect("a real classes.dex must read");
        assert!(!sink.has_blocking(), "{:?}", sink.entries());
        assert_eq!(
            sink.entries().len(),
            0,
            "a package this build produced must be intact: {:?}",
            sink.entries()
        );

        let number = |key: &str| -> u32 {
            let raw = fields
                .get(key)
                .unwrap_or_else(|| panic!("dexdump printed no {key}"));
            raw.split_whitespace()
                .next()
                .unwrap()
                .parse()
                .unwrap_or_else(|_| panic!("{key} = {raw:?}"))
        };

        assert_eq!(fields.get("magic").unwrap(), "'dex\\n039\\0'");
        assert_eq!(file.header.version, "039");
        assert_eq!(file.header.file_size, number("file_size"));
        assert_eq!(file.header.header_size, number("header_size"));
        assert_eq!(file.header.string_ids_size, number("string_ids_size"));
        assert_eq!(file.header.type_ids_size, number("type_ids_size"));
        assert_eq!(file.header.proto_ids_size, number("proto_ids_size"));
        assert_eq!(file.header.field_ids_size, number("field_ids_size"));
        assert_eq!(file.header.method_ids_size, number("method_ids_size"));
        assert_eq!(file.header.class_defs_size, number("class_defs_size"));

        assert_eq!(file.strings.len(), file.header.string_ids_size as usize);
        assert_eq!(file.types.len(), file.header.type_ids_size as usize);
        assert_eq!(file.fields.len(), file.header.field_ids_size as usize);
        assert_eq!(file.methods.len(), file.header.method_ids_size as usize);
        assert_eq!(file.classes.len(), file.header.class_defs_size as usize);

        let expected: Vec<String> = descriptors
            .iter()
            .map(|d| dex::descriptor_to_source(d))
            .collect();
        assert_eq!(file.class_names(), expected);

        let integrity = dex::integrity(&bytes).unwrap();
        assert!(integrity.checksum_matches());
        assert!(integrity.signature_matches());

        eprintln!(
            "dex conformance: {} classes, {} methods, {} strings; header and class \
             list agree with dexdump",
            file.classes.len(),
            file.methods.len(),
            file.strings.len()
        );
    }

    fn minimal_class(long_first: bool) -> Vec<u8> {
        let mut pool: Vec<u8> = Vec::new();
        let mut next = 1u16;

        if long_first {
            pool.push(5);
            pool.extend_from_slice(&1_234_567_890_123u64.to_be_bytes());
            next += 2;
        }

        let name_index = next;
        pool.push(1);
        pool.extend_from_slice(&4u16.to_be_bytes());
        pool.extend_from_slice(b"Test");
        next += 1;

        let this_index = next;
        pool.push(7);
        pool.extend_from_slice(&name_index.to_be_bytes());
        next += 1;

        let object_name_index = next;
        pool.push(1);
        pool.extend_from_slice(&16u16.to_be_bytes());
        pool.extend_from_slice(b"java/lang/Object");
        next += 1;

        let super_index = next;
        pool.push(7);
        pool.extend_from_slice(&object_name_index.to_be_bytes());
        next += 1;

        let mut data: Vec<u8> = Vec::new();
        data.extend_from_slice(&jvm::MAGIC.to_be_bytes());
        data.extend_from_slice(&0u16.to_be_bytes());
        data.extend_from_slice(&61u16.to_be_bytes());
        data.extend_from_slice(&next.to_be_bytes());
        data.extend_from_slice(&pool);
        data.extend_from_slice(&0x0021u16.to_be_bytes());
        data.extend_from_slice(&this_index.to_be_bytes());
        data.extend_from_slice(&super_index.to_be_bytes());
        data.extend_from_slice(&0u16.to_be_bytes());
        data.extend_from_slice(&0u16.to_be_bytes());
        data.extend_from_slice(&0u16.to_be_bytes());
        data.extend_from_slice(&0u16.to_be_bytes());
        data
    }

