    #[test]
    fn the_developers_own_key_signs_the_package_and_apksigner_reads_their_name() {
        let Some(apksigner) = find_apksigner() else {
            assert!(
                std::env::var("OMNI_REQUIRE_SELF_BUILT_APK").is_err(),
                "OMNI_REQUIRE_SELF_BUILT_APK is set but apksigner is missing"
            );
            eprintln!("developer key: apksigner is not available here");
            return;
        };

        let directory = temp_directory("omni-developer");
        let folder = directory.to_str().unwrap().to_string();
        let password = "the developer's own password";
        let request = super::keystore::Request {
            alias: "eaquel-release".to_string(),
            common_name: "Eaquel Release".to_string(),
            organisation: "Omni Builder".to_string(),
            country: "TR".to_string(),
            validity_days: 10_950,
            bits: 2048,
        };
        let made = super::keystore::create(&folder, &request, password, 1_787_000_000).unwrap();
        let opened = super::keystore::unlock(&made.path, password).unwrap();

        let mut sink = Sink::new();
        let project = super::builder::starter("com.tr.yt", "Omni");
        let outcome =
            super::builder::assemble(&project, &opened.key, &opened.certificate, &mut sink)
                .expect("the developer's key must sign the package");
        assert_eq!(outcome.certificate_fingerprint, made.fingerprint);

        assert!(outcome.verified.everything_checkable_passed());
        assert!(outcome.verified.signatures_checked);
        assert_eq!(outcome.verified.signatures_failed, 0);
        assert!(outcome.verified.signatures_verified >= 2, "v2 and v3 both");
        assert!(outcome.verified.key_matches_certificate);
        assert_eq!(outcome.verified.digests_failed, 0);

        let path = directory.join("developer-signed.apk");
        std::fs::write(&path, &outcome.package).unwrap();
        let verified = std::process::Command::new(&apksigner)
            .args([
                "verify",
                "--verbose",
                "--print-certs",
                "--min-sdk-version",
                &crate::compiler::OLDEST_API.to_string(),
                path.to_str().unwrap(),
            ])
            .output()
            .unwrap();
        let report = format!(
            "{}{}",
            String::from_utf8_lossy(&verified.stdout),
            String::from_utf8_lossy(&verified.stderr)
        );
        assert!(verified.status.success(), "{report}");
        assert!(
            report.contains("Verified using v3 scheme (APK Signature Scheme v3): true"),
            "{report}"
        );
        assert!(report.contains("CN=Eaquel Release"), "{report}");
        assert!(report.contains("O=Omni Builder"), "{report}");
        assert!(
            report
                .to_lowercase()
                .contains(&made.fingerprint.replace(':', "").to_lowercase()),
            "apksigner must report the same certificate the keys list shows\n{report}"
        );

        std::fs::remove_dir_all(&directory).ok();
        eprintln!(
            "developer key: apksigner read CN=Eaquel Release off a package this build signed"
        );
    }

    #[test]
    fn the_security_policy_reports_a_weak_package_without_stopping_it() {
        let _turn = super::progress::one_at_a_time();
        let key = super::rsa::generate(1024).unwrap();
        let cases: &[(&str, &str, &str)] = &[
            (
                "debuggable",
                r#"<application android:label="X" android:allowBackup="false" android:debuggable="true" />"#,
                "EG001",
            ),
            (
                "cleartext",
                r#"<application android:label="X" android:allowBackup="false" android:usesCleartextTraffic="true" />"#,
                "EG002",
            ),
            ("backup", r#"<application android:label="X" />"#, "EG003"),
            (
                "exported",
                r#"<application android:label="X" android:allowBackup="false"><activity android:name="A" android:exported="true"><intent-filter><action android:name="x" /></intent-filter></activity></application>"#,
                "EG004",
            ),
            (
                "provider",
                r#"<application android:label="X" android:allowBackup="false"><provider android:name="P" android:authorities="a" android:exported="true" android:grantUriPermissions="true" /></application>"#,
                "EG005",
            ),
            (
                "legacy storage",
                r#"<application android:label="X" android:allowBackup="false" android:requestLegacyExternalStorage="true" />"#,
                "EG009",
            ),
            (
                "task hijacking",
                r#"<application android:label="X" android:allowBackup="false"><activity android:name="A" android:exported="true" android:launchMode="singleTask"><intent-filter><action android:name="x" /></intent-filter></activity></application>"#,
                "EG011",
            ),
        ];

        for (name, application, code) in cases {
            let manifest = format!(
                r#"<?xml version="1.0" encoding="utf-8"?>
<manifest xmlns:android="http://schemas.android.com/apk/res/android" package="com.omni.weak">
    <uses-sdk android:minSdkVersion="30" android:targetSdkVersion="36" />
    {application}
</manifest>"#
            );
            let project = super::builder::Project {
                manifest,
                files: Vec::new(),
                code: Vec::new(),
                references: Vec::new(),
                identity: super::builder::Identity::default(),
                icon: None,
                launcher: Vec::new(),
                values: Vec::new(),
                resources: Vec::new(),
                library_values: Vec::new(),
                library_resources: Vec::new(),
                library_packages: Vec::new(),
                sealed: None,
                shrink: true,
                seal_resources: false,
            };
            let mut sink = Sink::new();
            let built = super::builder::build(&project, &key, 1_787_000_000, &mut sink)
                .unwrap_or_else(|why| panic!("{name} must still be produced: {why:?}"));
            assert!(built.signed, "{name}");
            let codes: Vec<&str> = sink.entries().iter().map(|d| d.code.as_str()).collect();
            assert!(
                codes.contains(code),
                "{name}: expected {code}, got {codes:?}"
            );
            assert!(
                sink.entries()
                    .iter()
                    .filter(|one| one.code == *code)
                    .all(|one| !one.severity.is_blocking()),
                "{name}: a policy finding must not block a build"
            );
            assert!(
                built.guard.findings.iter().any(|one| one.code == *code),
                "{name}: the report must carry the finding"
            );
        }
    }

    #[test]
    fn a_shared_user_identity_and_a_census_of_every_application_are_refused() {
        let manifest = r#"<?xml version="1.0" encoding="utf-8"?>
<manifest xmlns:android="http://schemas.android.com/apk/res/android" package="com.omni.weak"
    android:sharedUserId="com.omni.shared">
    <uses-sdk android:minSdkVersion="30" android:targetSdkVersion="36" />
    <uses-permission android:name="android.permission.QUERY_ALL_PACKAGES" />
    <application android:label="X" android:allowBackup="false" android:hasCode="false"
        android:extractNativeLibs="false" />
</manifest>"#;

        let mut sink = Sink::new();
        let root = super::xml::parse(manifest, "AndroidManifest.xml", &mut sink).unwrap();
        let report = super::guard::inspect_manifest(&root);
        assert_eq!(report.verdict(), super::guard::Verdict::Refused);

        let codes: Vec<&str> = report.findings.iter().map(|one| one.code).collect();
        assert!(codes.contains(&"EG008"), "{codes:?}");
        assert!(codes.contains(&"EG010"), "{codes:?}");

        for finding in &report.findings {
            assert!(!finding.why.is_empty(), "{} says nothing", finding.code);
            assert!(
                !finding.remedy.is_empty(),
                "{} offers nothing",
                finding.code
            );
        }
    }

