        assert!(parse_manifest(manifest, "com.f", &mut sink).is_none());
        let error = sink.entries().iter().find(|d| d.code == "E3008").unwrap();
        assert!(
            !error.message.contains("Name"),
            "a key belongs in a context line"
        );
        assert!(error.context.iter().any(|line| line == "Key: Name"));
        assert!(error.context.iter().any(|line| line == "Section: Project"));
